<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { message } from 'ant-design-vue';
import { IconifyIcon } from '@vben/icons';
import { VbenAvatar, VbenButton, useVbenModal } from '@vben/common-ui';
import { useUserStore } from '@vben/stores';
import { useVbenForm } from '#/adapter/form';
import { requestClient } from '#/api/request';
import { $t } from '#/locales';
import { useAuthStore } from '#/store';
interface AdminProfile { id:string;username:string;realName:string;avatar:string;roles:string[];email:string;emailVerified:boolean; }
const loading=ref(false),saving=ref(false),uploading=ref(false),emailSending=ref(false),emailVerifying=ref(false);
const email=ref(''),emailCode=ref(''),emailVerified=ref(false);
const profile=reactive<AdminProfile>({id:'',username:'',realName:'',avatar:'',roles:[],email:'',emailVerified:false});
const userStore=useUserStore(),authStore=useAuthStore();const passwordSaving=ref(false);
const [PasswordModal,passwordModalApi]=useVbenModal({title:$t('tg-card.profile.changePassword'),onConfirm:submitPassword});
const [ProfileForm,profileFormApi]=useVbenForm({commonConfig:{componentProps:{class:'w-full'}},layout:'vertical',showDefaultActions:false,wrapperClass:'grid-cols-1',schema:[{component:'Input',fieldName:'realName',label:$t('tg-card.profile.nickname'),componentProps:{maxlength:80,placeholder:$t('tg-card.profile.nicknamePlaceholder')}}]});
const [AvatarForm]=useVbenForm({commonConfig:{componentProps:{class:'w-full'}},layout:'vertical',showDefaultActions:false,wrapperClass:'grid-cols-1',schema:[{component:'Upload',fieldName:'avatarFile',label:$t('tg-card.profile.avatarUpload'),componentProps:{accept:'image/jpeg,image/png,image/webp,image/gif,image/bmp,image/tiff,image/avif,image/heic,image/heif',listType:'picture',maxCount:1,showUploadList:false,beforeUpload:uploadAvatar}}]});
const [PasswordForm,passwordFormApi]=useVbenForm({commonConfig:{componentProps:{class:'w-full'}},layout:'vertical',showDefaultActions:false,wrapperClass:'grid-cols-1',schema:[{component:'InputPassword',fieldName:'currentPassword',label:$t('tg-card.profile.currentPassword'),componentProps:{autocomplete:'current-password',placeholder:$t('tg-card.profile.currentPasswordPlaceholder')}},{component:'InputPassword',fieldName:'newPassword',label:$t('tg-card.profile.newPassword'),componentProps:{autocomplete:'new-password',placeholder:$t('tg-card.profile.newPasswordPlaceholder')}},{component:'InputPassword',fieldName:'confirmPassword',label:$t('tg-card.profile.confirmPassword'),componentProps:{autocomplete:'new-password',placeholder:$t('tg-card.profile.confirmPasswordPlaceholder')}}]});
function roleLabel(){return profile.roles.some(x=>['super','SUPER_ADMIN','admin'].includes(x))?$t('tg-card.profile.superAdmin'):$t('tg-card.profile.admin');}
async function loadProfile(){loading.value=true;try{const data=await requestClient.get<AdminProfile>('/user/info');Object.assign(profile,data);email.value=data.email||'';emailVerified.value=!!data.emailVerified;await profileFormApi.setValues({realName:data.realName||''});userStore.setUserInfo(data as any);}catch{message.error($t('tg-card.profile.profileLoadFailed'));}finally{loading.value=false;}}
async function saveProfile(){const {valid}=await profileFormApi.validate();if(!valid)return;const values=await profileFormApi.getValues();saving.value=true;try{const result=await requestClient.put<{realName:string;avatar:string}>('/user/profile',{realName:String(values.realName||'').trim(),avatar:profile.avatar});profile.realName=result.realName;profile.avatar=result.avatar;const updated=await requestClient.get<AdminProfile>('/user/info');Object.assign(profile,updated);userStore.setUserInfo(updated as any);message.success($t('tg-card.profile.profileSaved'));}catch(error:any){message.error(error?.response?.data?.message||$t('tg-card.profile.profileSaveFailed'));}finally{saving.value=false;}}
async function uploadAvatar(file:any){const image=file?.originFileObj||file;if(!(image instanceof Blob)){message.error($t('tg-card.profile.avatarReadFailed'));return false;}if(image.size>20*1024*1024){message.warning($t('tg-card.profile.avatarTooLarge'));return false;}uploading.value=true;try{const body=new FormData();body.append('file',image,image.name||'avatar');const result=await requestClient.post<{avatar:string}>('/user/avatar',body,{headers:{'Content-Type':'multipart/form-data'}});profile.avatar=result.avatar;message.success($t('tg-card.profile.avatarUploaded'));}catch(error:any){message.error(error?.response?.data?.message||$t('tg-card.profile.avatarUploadFailed'));}finally{uploading.value=false;}return false;}
async function sendEmailCode(){if(!email.value.trim()){message.warning($t('tg-card.profile.emailRequired'));return;}emailSending.value=true;try{await requestClient.post('/user/email/send-code',{email:email.value.trim()});message.success($t('tg-card.profile.emailCodeSent'));}catch(error:any){message.error(error?.response?.data?.message||$t('tg-card.profile.emailCodeSendFailed'));}finally{emailSending.value=false;}}
async function verifyEmail(){if(!email.value.trim()||!/^\d{6}$/.test(emailCode.value)){message.warning($t('tg-card.profile.emailCodeRequired'));return;}emailVerifying.value=true;try{await requestClient.post('/user/email/verify',{email:email.value.trim(),code:emailCode.value.trim()});emailVerified.value=true;message.success($t('tg-card.profile.emailBound'));await loadProfile();}catch(error:any){message.error(error?.response?.data?.message||$t('tg-card.profile.emailVerifyFailed'));}finally{emailVerifying.value=false;}}
function openPasswordModal(){void passwordFormApi.setValues({currentPassword:'',newPassword:'',confirmPassword:''});passwordModalApi.open();}
async function submitPassword(){const {valid}=await passwordFormApi.validate();if(!valid)return;const values=await passwordFormApi.getValues();if(String(values.newPassword||'').length<12){message.warning($t('tg-card.profile.passwordTooShort'));return;}if(values.newPassword!==values.confirmPassword){message.warning($t('tg-card.profile.passwordMismatch'));return;}passwordSaving.value=true;try{await requestClient.post('/admin/password',{currentPassword:values.currentPassword,newPassword:values.newPassword});passwordModalApi.close();message.success($t('tg-card.profile.passwordChanged'));await authStore.logout();}catch(error:any){message.error(error?.response?.data?.message||$t('tg-card.profile.passwordChangeFailed'));}finally{passwordSaving.value=false;}}
onMounted(loadProfile);
</script>
<template>
<div class="mx-auto flex w-full min-w-0 max-w-5xl flex-col gap-4 p-3 md:p-6">
 <a-card :bordered="false" :loading="loading"><div class="flex min-w-0 flex-col items-center gap-4 sm:flex-row"><VbenAvatar :src="profile.avatar||undefined" class="size-20 shrink-0"/><div class="min-w-0 flex-1 text-center sm:text-left"><div class="break-all text-lg font-semibold">{{profile.realName||profile.username||$t('tg-card.profile.admin')}}</div><div class="mt-1 break-all text-sm text-gray-500">{{$t('tg-card.profile.loginAccount')}}：{{profile.username}}</div><div class="mt-2 flex flex-wrap justify-center gap-2 sm:justify-start"><a-tag color="blue">{{roleLabel()}}</a-tag><a-tag color="success">{{$t('tg-card.profile.accountNormal')}}</a-tag></div></div><div class="w-full sm:w-auto"><AvatarForm/><a-spin v-if="uploading" size="small"/></div></div></a-card>
 <div class="grid grid-cols-1 gap-4 md:grid-cols-2">
  <a-card :bordered="false"><template #title><div class="flex items-center gap-3"><span class="flex h-10 w-10 items-center justify-center rounded-lg border border-blue-100 bg-white text-blue-600"><IconifyIcon icon="mdi:shield-lock-outline" class="text-xl"/></span><span>{{$t('tg-card.profile.accountSecurity')}}</span></div></template><div class="space-y-3 text-sm"><div class="flex justify-between gap-3"><span class="text-gray-500">登录账号</span><span class="break-all font-medium">{{profile.username}}</span></div><div class="flex justify-between gap-3"><span class="text-gray-500">账户角色</span><span class="font-medium">{{roleLabel()}}</span></div><div class="flex justify-between gap-3"><span class="text-gray-500">邮箱状态</span><a-tag :color="emailVerified?'success':'default'">{{emailVerified?$t('tg-card.profile.verified'):$t('tg-card.profile.unbound')}}</a-tag></div></div></a-card>
  <a-card :bordered="false"><template #title><div class="flex items-center gap-3"><span class="flex h-10 w-10 items-center justify-center rounded-lg border border-blue-100 bg-white text-blue-600"><IconifyIcon icon="mdi:account-edit-outline" class="text-xl"/></span><span>{{$t('tg-card.profile.basicProfile')}}</span></div></template><ProfileForm/><div class="mt-4 flex justify-end"><VbenButton type="primary" :loading="saving" @click="saveProfile">{{$t('tg-card.profile.saveProfile')}}</VbenButton></div></a-card>
  <a-card :bordered="false"><template #title><div class="flex items-center gap-3"><span class="flex h-10 w-10 items-center justify-center rounded-lg border border-blue-100 bg-white text-blue-600"><IconifyIcon icon="mdi:email-check-outline" class="text-xl"/></span><span>{{$t('tg-card.profile.emailBinding')}}</span></div></template><a-alert v-if="emailVerified" type="success" show-icon :message="$t('tg-card.profile.emailVerified')" class="mb-3"/><a-form layout="vertical"><a-form-item :label="$t('tg-card.profile.emailAddress')"><a-input v-model:value="email" type="email" :placeholder="$t('tg-card.profile.emailPlaceholder')" :disabled="emailVerified"/></a-form-item><a-form-item v-if="!emailVerified" :label="$t('tg-card.profile.emailCode')"><div class="flex gap-2"><a-input v-model:value="emailCode" maxlength="6" inputmode="numeric" :placeholder="$t('tg-card.profile.emailCodePlaceholder')"/><a-button :loading="emailSending" @click="sendEmailCode">{{$t('tg-card.profile.sendCode')}}</a-button></div></a-form-item></a-form><div v-if="!emailVerified" class="flex justify-end"><a-button type="primary" :loading="emailVerifying" @click="verifyEmail">{{$t('tg-card.profile.verifyBind')}}</a-button></div><div v-else class="text-xs text-gray-500">{{$t('tg-card.profile.boundEmail')}}{{email}}</div></a-card>
  <a-card :bordered="false"><template #title><div class="flex items-center gap-3"><span class="flex h-10 w-10 items-center justify-center rounded-lg border border-blue-100 bg-white text-blue-600"><IconifyIcon icon="mdi:lock-reset" class="text-xl"/></span><span>{{$t('tg-card.profile.passwordCard')}}</span></div></template><div class="mb-4 text-sm leading-6 text-gray-500">{{$t('tg-card.profile.passwordAdvice')}}</div><div class="flex justify-end"><a-button type="primary" @click="openPasswordModal">{{$t('tg-card.profile.changePassword')}}</a-button></div></a-card>
 </div>
 <PasswordModal class="w-full max-w-lg" :confirm-loading="passwordSaving"><div class="p-4 sm:p-6"><PasswordForm/></div></PasswordModal>
</div>
</template>